dataset_headers = []
dataset_rows = []
dataset_lines = DATASET_CSV.split("\\n")
for dataset_line in dataset_lines:
    if dataset_line.strip() != "":
        dataset_values = dataset_line.split(",")
        if len(dataset_headers) == 0:
            dataset_headers = dataset_values
        else:
            dataset_record = {}
            for dataset_i in range(len(dataset_headers)):
                dataset_record[dataset_headers[dataset_i]] = float(dataset_values[dataset_i])
            dataset_rows.append(dataset_record)

dataset_index = 0
dataset_last_time = 0.0
dataset_mode = True
dataset_record = dataset_rows[0] if len(dataset_rows) > 0 else {}

# ================================================================
# INTEGRATED PLANT PROCESS MODEL (from the second Web-VPython model)
# ================================================================
# This subsystem adds a simple spent-fuel/cooling process model to the
# inspection scenario.  It is independent of the mobile robot dynamics.
# Pool equations:
#   dL/dt = flow - leak - boil
#   dT/dt = heat_input - cooling - flow_effect
# A small PID regulates the pool level toward its setpoint.

pool_setpoint = 8.0
power = 80.0
plant_power = power
paused = False
sim_speed = 1.0

class PlantPID:
    def __init__(self, kp, ki, kd, lo, hi):
        self.kp = kp
        self.ki = ki
        self.kd = kd
        self.lo = lo
        self.hi = hi
        self.integral = 0.0
        self.previous = 0.0

    def update(self, error, dt):
        if dt <= 0:
            dt = 0.001
        derivative = (error - self.previous) / dt
        self.integral += error * dt
        self.integral = clamp(self.integral, -10.0, 10.0)
        self.previous = error
        u = self.kp*error + self.ki*self.integral + self.kd*derivative
        return clamp(u, self.lo, self.hi)

class PoolProcess:
    def __init__(self):
        self.level = 8.0
        self.temperature = 32.0
        self.flow = 1.5
        self.leak = 0.0
        self.boil = 0.0
        self.pid = PlantPID(2.0, 0.25, 0.3, 0.0, 4.0)

    def update(self, dt, power, leak_on):
        error = pool_setpoint - self.level
        command = self.pid.update(error, dt)
        self.flow += (command - self.flow) * dt / 1.5
        self.flow = clamp(self.flow, 0.0, 4.0)

        if leak_on:
            self.leak = 0.9 * sqrt(max(self.level, 0.0))
        else:
            self.leak = 0.0

        self.boil = max(0.0, (power - 70.0) * 0.008)
        dlevel = (self.flow - self.leak - self.boil) * dt
        self.level = clamp(self.level + dlevel, 0.5, 10.0)

        heat = 0.02 * power
        cooling = 0.015 * (self.temperature - 25.0)
        self.temperature += (heat - cooling - 0.01*self.flow) * dt

plant_pool = PoolProcess()

# Visual process equipment from the second model, placed inside the
# existing plant layout without replacing the original UI.
spent_pool = box(
    pos=vector(-25, 1.8, -27),
    size=vector(13, 3.6, 9),
    color=color.cyan,
    opacity=0.55
)
spent_pool_frame1 = box(pos=vector(-25,3.8,-31.5), size=vector(15,0.3,0.4), color=color.gray(0.7))
spent_pool_frame2 = box(pos=vector(-25,3.8,-22.5), size=vector(15,0.3,0.4), color=color.gray(0.7))
