def toggle_pause(b):
    global paused
    paused = not paused
    b.text = "RESUME" if paused else "PAUSE"

button(text="PAUSE", bind=toggle_pause)
scene.append_to_caption("   ")

# Same anomaly controls as the second Web-VPython model.
def anomaly_change(m):
    global manual_anomaly, manual_anomaly_active
    manual_anomaly = m.selected
    if manual_anomaly == ANOMALY_NONE:
        manual_anomaly_active = False
        anomaly_marker.visible = False
        anomaly_text.visible = False
    else:
        manual_anomaly_active = True
        anomaly_marker.visible = True
        anomaly_text.visible = True
        if manual_anomaly == ANOMALY_COOLANT:
            anomaly_marker.pos = vector(5, 3, -15)
            anomaly_text.pos = vector(5, 5, -15)
            anomaly_text.text = "COOLANT LEAK TEST"
        elif manual_anomaly == ANOMALY_STEAM:
            anomaly_marker.pos = vector(-5, 8, 10)
            anomaly_text.pos = vector(-5, 10, 10)
            anomaly_text.text = "STEAM RUPTURE TEST"
        elif manual_anomaly == ANOMALY_RADIATION:
            anomaly_marker.pos = vector(-25, 5, -5)
            anomaly_text.pos = vector(-25, 7, -5)
            anomaly_text.text = "RADIATION HOTSPOT TEST"
        else:
            anomaly_marker.pos = vector(38, 4, -25)
            anomaly_text.pos = vector(38, 6, -25)
            anomaly_text.text = "SWITCHYARD FIRE TEST"

anomaly_menu = menu(
    choices=["None", "Coolant Leak", "Steam Rupture", "Radiation Hotspot", "Transformer Fire"],
    selected="None", bind=anomaly_change
)

scene.append_to_caption("\nPower ")
def power_change(sld):
    global power, plant_power
    power = sld.value
    plant_power = power

power_slider = slider(min=20, max=100, value=80, length=180, bind=power_change)

scene.append_to_caption("   Pool setpoint ")
def sp_change(sld):
    global pool_setpoint
    pool_setpoint = sld.value

sp_slider = slider(min=5, max=9.5, value=8, length=180, bind=sp_change)

scene.append_to_caption("\nSimulation speed ")
def speed_change(sld):
    global sim_speed
    sim_speed = sld.value

speed_slider = slider(min=0.5, max=3, value=1, length=180, bind=speed_change)
scene.append_to_caption("\n")

# Robot controller controls remain available without adding extra graphs.
scene.append_to_caption("Controller ")
def controller_change(m):
    global controller_mode
    controller_mode = m.selected
    robot_controller.reset()

controller_menu = menu(choices=["SMC", "PID"], selected="SMC", bind=controller_change)
scene.append_to_caption("   Disturbance ")

def disturbance_change(sld):
    global disturbance_strength
    disturbance_strength = sld.value

disturbance_slider = slider(min=0, max=3, value=0, length=140, bind=disturbance_change)
