# ================================================================
# SEPARATE PID AND SMC GRAPHS — TWO GRAPHS PER SECTION
# Graphs are created in matching PID-left / SMC-right pairs; each pair forms one row.
# Each controller keeps its own curves/history. Error graphs remain removed.
# ================================================================

# Section 1: XY trajectory
pid_traj_graph = graph(title="PID — Desired vs Actual Trajectory", xtitle="X position (m)", ytitle="Y position (m)", width=850, height=210, align="left")
pid_desired_traj_curve = gcurve(color=color.cyan, label="Desired patrol path")
pid_actual_traj_curve = gcurve(color=color.red, label="PID actual path")
for _wp in wp_patrol:
    pid_desired_traj_curve.plot(_wp.x, _wp.z)

smc_traj_graph = graph(title="SMC — Desired vs Actual Trajectory", xtitle="X position (m)", ytitle="Y position (m)", width=850, height=210, align="left")
smc_desired_traj_curve = gcurve(color=color.cyan, label="Desired patrol path")
