# ================================================================
# ================================================================
# MATHEMATICAL MODEL + PID + SLIDING MODE CONTROLLER
# ================================================================
# The 4 visual wheels are treated mathematically as a differential-drive
# equivalent: FL+RL = left drive side, FR+RR = right drive side.
#
# Kinematics:
#   vL=r*wL, vR=r*wR
#   v=(vR+vL)/2, omega=(vR-vL)/B
#   x_dot=v*cos(theta), y_dot=v*sin(theta), theta_dot=omega
#
# Dynamics:
#   m*v_dot=(tauL+tauR)/r-cv*v-Fd
#   Iz*omega_dot=B*(tauR-tauL)/(2*r)-cw*omega-Td
#
# Controllers:
#   PID = conventional trajectory-tracking baseline
#   SMC = model-based robust controller for the proposed system
# ================================================================

def sat(x):
    if x > 1:
        return 1
    if x < -1:
        return -1
    return x

def smooth_sign(x, boundary):
    if boundary <= 0.0001:
        return sat(x)
    return sat(x / boundary)

def random_choice(items):
    if len(items) == 0:
        return None
    idx = int(random() * len(items))
    if idx >= len(items):
        idx = len(items) - 1
    return items[idx]

class DifferentialDriveController:
    def __init__(self, wheel_radius=0.5, track_width=2.4):
        self.r = wheel_radius
        self.B = track_width

        # Physical robot parameters
        self.mass = 50.0
        self.Iz = 12.0
        self.c_v = 5.0
        self.c_w = 2.5
        self.max_torque = 45.0
        self.max_v = 0.75
        self.max_w = 1.25
        self.max_wheel_speed = 3.0

        # PID baseline
        self.kp_v = 0.65
        self.ki_v = 0.008
        self.kd_v = 0.10
        self.kp_w = 2.2
        self.ki_w = 0.015
        self.kd_w = 0.12

        # SMC gains
        self.smc_kv = 2.8
        self.smc_kw = 3.5
        self.smc_eta_v = 0.55
        self.smc_eta_w = 0.85
        self.smc_phi = 0.08

        self.reset()

    def reset(self):
        self.v_integral = 0.0
        self.v_prev_error = 0.0
        self.w_integral = 0.0
        self.w_prev_error = 0.0
        self.v = 0.0
        self.omega = 0.0
        self.wL = 0.0
        self.wR = 0.0
        self.v_p = self.v_i = self.v_d = self.v_pid = 0.0
        self.w_p = self.w_i = self.w_d = self.w_pid = 0.0
        self.v_cmd = 0.0
        self.omega_cmd = 0.0
        self.tau_L = 0.0
        self.tau_R = 0.0
        self.v_dot = 0.0
        self.omega_dot = 0.0
        self.s_v = 0.0
        self.s_w = 0.0

    def wrap_angle(self, a):
        while a > pi:
            a -= 2*pi
        while a < -pi:
            a += 2*pi
        return a

    def inverse_kinematics(self, v, omega):
        vL = v - self.B*omega/2.0
        vR = v + self.B*omega/2.0
        self.wL = clamp(vL/self.r, -self.max_wheel_speed, self.max_wheel_speed)
        self.wR = clamp(vR/self.r, -self.max_wheel_speed, self.max_wheel_speed)

    def pid_reference(self, x, y, theta, tx, ty, dt):
        dx = tx-x
        dy = ty-y
        rho = sqrt(dx*dx + dy*dy)
        desired_heading = atan2(dy, dx)
        alpha = self.wrap_angle(desired_heading-theta)

        self.v_integral += rho*dt
        self.v_integral = clamp(self.v_integral, -8, 8)
        vd = (rho-self.v_prev_error)/max(dt,0.0001)
        self.v_p = self.kp_v*rho
        self.v_i = self.ki_v*self.v_integral
        self.v_d = self.kd_v*vd
        self.v_pid = self.v_p+self.v_i+self.v_d
        self.v_prev_error = rho

        self.w_integral += alpha*dt
        self.w_integral = clamp(self.w_integral, -6, 6)
        wd = (alpha-self.w_prev_error)/max(dt,0.0001)
        self.w_p = self.kp_w*alpha
        self.w_i = self.ki_w*self.w_integral
        self.w_d = self.kd_w*wd
        self.w_pid = self.w_p+self.w_i+self.w_d
        self.w_prev_error = alpha

        vref = clamp(self.v_pid, -self.max_v, self.max_v)
        wref = clamp(self.w_pid, -self.max_w, self.max_w)
        if abs(alpha) > 1.2:
            vref *= 0.25
        self.v_cmd = vref
        self.omega_cmd = wref
        return [vref, wref, rho, alpha]

    def smc_reference(self, x, y, theta, tx, ty):
        dx = tx-x
        dy = ty-y
        rho = sqrt(dx*dx + dy*dy)
        desired_heading = atan2(dy, dx)
        alpha = self.wrap_angle(desired_heading-theta)

        # Nonlinear reference + heading correction
        vref = self.max_v * sat(0.9*rho) * cos(alpha)
        wref = clamp(2.8*alpha, -self.max_w, self.max_w)

        if abs(alpha) > 1.35:
            vref *= 0.10
        elif abs(alpha) > 0.9:
            vref *= 0.35

        self.v_cmd = vref
        self.omega_cmd = wref
        return [vref, wref, rho, alpha]

    def compute_torques(self, vref, wref, dt, disturbance):
        if controller_mode == "PID":
            # PID gives the desired body velocity. The dynamic model
            # converts the required accelerations into wheel torques.
            av = clamp((vref-self.v)/max(dt,0.0001), -3.0, 3.0)
            aw = clamp((wref-self.omega)/max(dt,0.0001), -5.0, 5.0)
            self.s_v = self.v-vref
            self.s_w = self.omega-wref
        else:
            # Sliding surfaces and robust switching terms.
            self.s_v = self.v-vref
            self.s_w = self.omega-wref
            av = self.smc_kv*(vref-self.v) - self.smc_eta_v*smooth_sign(self.s_v,self.smc_phi)
            aw = self.smc_kw*(wref-self.omega) - self.smc_eta_w*smooth_sign(self.s_w,self.smc_phi)
            av = clamp(av, -3.5, 3.5)
            aw = clamp(aw, -6.0, 6.0)

        # Inverse dynamics -> left/right motor torques
        tau_sum = self.r*(self.mass*av + self.c_v*self.v + disturbance["force"])
        tau_diff = (2.0*self.r/self.B)*(self.Iz*aw + self.c_w*self.omega + disturbance["moment"])
        self.tau_L = clamp(0.5*(tau_sum-tau_diff), -self.max_torque, self.max_torque)
        self.tau_R = clamp(0.5*(tau_sum+tau_diff), -self.max_torque, self.max_torque)

    def dynamics_step(self, dt, disturbance):
        self.v_dot = ((self.tau_L+self.tau_R)/self.r
                      - self.c_v*self.v - disturbance["force"]) / self.mass
        self.omega_dot = ((self.B/(2.0*self.r))*(self.tau_R-self.tau_L)
                          - self.c_w*self.omega - disturbance["moment"]) / self.Iz

        self.v += self.v_dot*dt
        self.omega += self.omega_dot*dt
        self.v = clamp(self.v,-self.max_v,self.max_v)
        self.omega = clamp(self.omega,-self.max_w,self.max_w)
        self.inverse_kinematics(self.v,self.omega)

    def step(self, x, y, theta, tx, ty, dt, disturbance):
        if controller_mode == "PID":
            ref = self.pid_reference(x,y,theta,tx,ty,dt)
        else:
            ref = self.smc_reference(x,y,theta,tx,ty)
        vref = ref[0]
        wref = ref[1]
        pos_error = ref[2]
        heading_error = ref[3]

        self.compute_torques(vref,wref,dt,disturbance)
        self.dynamics_step(dt,disturbance)

        x_next = x + self.v*cos(theta)*dt
        y_next = y + self.v*sin(theta)*dt
        theta_next = self.wrap_angle(theta+self.omega*dt)

        return [x_next,y_next,theta_next,self.v,self.omega,pos_error,heading_error]

    def hold(self, dt):
        self.tau_L = 0.0
        self.tau_R = 0.0
        self.v_dot = -self.c_v*self.v/self.mass
        self.omega_dot = -self.c_w*self.omega/self.Iz
        self.v += self.v_dot*dt
        self.omega += self.omega_dot*dt
        self.inverse_kinematics(self.v,self.omega)

# Mathematical state. VPython (x,z) maps to mathematical (x,y).
robot_x = -48.0
robot_y = 10.0
robot_theta = 0.0
robot_controller = DifferentialDriveController(wheel_radius=0.5, track_width=2.4)
robot_v = 0.0
robot_omega = 0.0
robot_pos_error = 0.0
robot_heading_error = 0.0
robot_wheel_commands = (0.0,0.0)

# Proposed controller = SMC; conventional baseline = PID.
controller_mode = "SMC"
disturbance_strength = 0.0

def get_motion_disturbance():
    d = {"force":0.0,"moment":0.0}
    if disturbance_strength > 0:
        d["force"] = disturbance_strength*(0.6+0.4*sin(scenario_timer*2.1))
        d["moment"] = 0.35*disturbance_strength*sin(scenario_timer*1.7)
    # Manual plant tests can also introduce controlled disturbances.
    if manual_anomaly == ANOMALY_COOLANT:
        d["force"] += 0.8
    elif manual_anomaly == ANOMALY_STEAM:
        d["moment"] += 0.35*sin(scenario_timer*2.5)
    elif manual_anomaly == ANOMALY_FIRE:
        d["force"] += 0.5

    # Scenario automatically introduces a small disturbance during danger.
    if scenario_phase >= 1 and scenario_phase <= 2:
        d["force"] += 1.5
        d["moment"] += 0.25*sin(scenario_timer*3.0)
    return d


# Mathematical robot state.  (x_m, y_m) maps to VPython (x, z).
robot_x = -48.0
robot_y = 10.0
robot_theta = 0.0
robot_controller = DifferentialDriveController(wheel_radius=0.5, track_width=2.4)
robot_v = 0.0
robot_omega = 0.0
robot_pos_error = 0.0
robot_heading_error = 0.0
robot_wheel_commands = (0.0, 0.0, 0.0, 0.0)


def move_toward(pos, target, spd):
    # Kept only for Robot 2 / legacy environment motion.
    diff = target - pos
    if mag(diff) < 0.4:
        return [pos, True]
    return [pos + norm(diff) * spd, False]


def rotate_ground_offset(local_x, local_z, theta):
    """Rotate a local robot-frame X-Z offset into the world X-Z plane."""
    return vector(
        local_x*cos(theta) - local_z*sin(theta),
        0,
        local_x*sin(theta) + local_z*cos(theta)
    )


def update_robot1(new_pos=None):
    """Render Robot 1 from the mathematical state (x, y, theta)."""
    global robot_x, robot_y, robot_theta

    if new_pos is not None:
        # Compatibility only; mathematical motion should use robot_x/robot_y.
        robot_x = new_pos.x
        robot_y = new_pos.z

    center = vector(robot_x, 1, robot_y)
    robot_body.pos = center

    # Rotate the chassis heading so the visual robot follows theta.
    robot_body.axis = vector(3*cos(robot_theta), 0, 3*sin(robot_theta))

    robot_head.pos = center + vector(0, 1.2, 0)

    wheel_offsets = [
        ( 1.2,  1.0),   # FL
        (-1.2,  1.0),   # RL
        ( 1.2, -1.0),   # FR
        (-1.2, -1.0),   # RR
    ]
    wheels = [wheel_fl, wheel_rl, wheel_fr, wheel_rr]
    axle_axis = vector(-sin(robot_theta), 0, cos(robot_theta)) * 0.9

    for wheel, (lx, lz) in zip(wheels, wheel_offsets):
        off = rotate_ground_offset(lx, lz, robot_theta)
        wheel.pos = center + off + vector(0, -0.5, 0)
        wheel.axis = axle_axis

    # Arm points in the robot's forward direction during normal motion.
    arm_base = center + rotate_ground_offset(1.5, 0, robot_theta) + vector(0, 0.5, 0)
    robot_arm.pos = arm_base

    robot_light.pos  = center + vector(0, 1.2, 0)
    robot_beacon.pos = center + vector(0, 1.8, 0)
    signal_ring.pos  = center + vector(0, 1.5, 0)
    robot1_label.pos = center + vector(0, 3.2, 0)


def update_robot2(new_pos):
    robot2_body.pos   = new_pos
    robot2_head.pos   = new_pos + vector(0, 1.5, 0)
    robot2_w1.pos     = new_pos + vector(-1.5,-0.5, 1)
    robot2_w2.pos     = new_pos + vector( 1.5,-0.5, 1)
    robot2_light.pos  = new_pos + vector(0, 2, 0)
    robot2_shield.pos = new_pos + vector(0, 0.5, 0)
    robot2_arm.pos    = new_pos + vector(1.5, 0.5, 0)
    robot2_label.pos  = new_pos + vector(0, 4.5, 0)


def battery_color(pct):
    if pct > 50: return color.green
    if pct > 20: return color.yellow
    return color.red

# ================================================
# MAIN LOOP
# ================================================

while True:

    rate(40)

    if paused:
        continue

    # 1.0x is real-time: 40 updates/s with dt=1/40 s.
    # 0.5x = slow motion, 2x/3x = accelerated simulation.
    dt = (1.0/40.0) * sim_speed
    scenario_timer += dt

    # Advance through the uploaded dataset according to simulation time.
    # The file has ~0.2 s sampling; select the latest record not after current time.
    while dataset_index < len(dataset_rows)-1 and dataset_rows[dataset_index+1]["time"] <= scenario_timer:
        dataset_index += 1
    if len(dataset_rows) > 0:
        dataset_record = dataset_rows[dataset_index]
    flash_timer    += dt
    rotor_angle    += 0.15
    spray_angle    += 0.08

    # ---- INTEGRATED PLANT PROCESS MODEL ----
    plant_leak = (scenario_phase >= 1 and scenario_phase <= 4) or manual_anomaly == ANOMALY_COOLANT
    plant_power_effective = power
    if manual_anomaly == ANOMALY_STEAM:
        plant_power_effective += 12.0
    plant_pool.update(dt, plant_power_effective, plant_leak)

    # ---- BATTERY / ENERGY MODEL ----
    # Robot consumption depends on motion rather than being a fixed random drain:
    #   P_relative = P_idle + k_v*|v| + k_w*|omega|
    # Battery is represented as percentage remaining.
    robot_consumption = (0.010 + 0.025*abs(robot_v) + 0.010*abs(robot_omega))
    robot_battery = max(0, robot_battery - robot_consumption * dt)
    drone_battery = max(0, drone_battery - DRONE_DRAIN * dt)

    robot_battery_low = robot_battery < ROBOT_LOW_THRESHOLD
    drone_battery_low = drone_battery < DRONE_LOW_THRESHOLD

    if robot_battery_low and "Robot battery LOW" not in " ".join(log_lines):
        add_log("!!! Robot 1 battery LOW: " + str(round(robot_battery,1)) + "%")
    if drone_battery_low and "Drone battery LOW" not in " ".join(log_lines):
        add_log("!!! Drone battery LOW: " + str(round(drone_battery,1)) + "%")

    # ---- PHASE TRANSITIONS ----

    if scenario_timer >= 80  and scenario_phase == 0:
        scenario_phase = 1
        add_log("ANOMALY: Gas rising at Zone C (Pump)")
        add_log("Robot 1 moving to investigate edge...")

    if scenario_timer >= 110 and scenario_phase == 1:
        scenario_phase = 2
        add_log("GAS LEAK CONFIRMED! Danger level HIGH")
        add_log("Robot 1 RETREATING to safe zone!")
        robot_body.color = color.yellow

    if scenario_timer >= 140 and scenario_phase == 2:
        scenario_phase = 3
        add_log("Robot 1 safe. Broadcasting alert signal.")
        add_log("Robot 2 (SHIELDED) deployed to Zone C!")
        for obj in [robot2_body, robot2_head, robot2_w1, robot2_w2, robot2_light, robot2_shield, robot2_arm, robot2_label]:
            obj.visible = True

    if scenario_timer >= 190 and scenario_phase == 3:
        scenario_phase = 4
        add_log("Robot 2 at Zone C. Spray arm ACTIVE.")
        add_log("Gas suppression in progress...")

    if scenario_timer >= 240 and scenario_phase == 4:
        scenario_phase = 5
        add_log("Gas sealed. Robot 2 signals ALL CLEAR.")
        add_log("Robot 1 resuming normal patrol!")
        robot_body.color     = color.orange
        robot_beacon.visible = False
        signal_ring.visible  = False
        wp_index = 0
        robot_controller.reset()

    # ================================================
    # ROBOT 1 MOVEMENT — MATHEMATICAL CONTROLLER
    # ================================================
    # Robot 1 no longer uses the old move_toward() patrol motion.
    # Every normal movement step is now:
    # SMC/PID -> inverse kinematics -> inverse dynamics -> torque -> robot dynamics.

    global_dummy = None  # keeps this section visually self-contained

    # Default controller target and mode.
    controller_target = None
    controller_active = False

    if scenario_phase == 0 or scenario_phase == 5:
        target_wp = wp_patrol[wp_index % len(wp_patrol)]
        target_x = target_wp.x
        target_y = target_wp.z
        controller_target = target_wp

        # --- PUMP STATION: reach target using PID, then inspect ---
        if (wp_index % len(wp_patrol)) == PUMP_INSPECT_WP and not is_inspecting:
            controller_active = True
        elif (wp_index % len(wp_patrol)) != PUMP_INSPECT_WP:
            controller_active = True

        if is_inspecting:
            # Hold the mathematical state while the arm performs inspection.
            robot_controller.hold(dt)
            robot_v = robot_controller.v
            robot_omega = robot_controller.omega
            inspect_timer += dt

            robot_arm.axis = vector(
                3.5*cos(inspect_timer*1.2),
                0,
                3.5*sin(inspect_timer*1.2)
            )

            if inspect_timer >= INSPECT_DURATION:
                is_inspecting = False
                robot_controller.reset()
                robot_arm.axis = vector(2, 0, 0)
                wp_index = (wp_index + 1) % len(wp_patrol)
                add_log("Pump inspection done. Continuing patrol.")
        else:
            state = robot_controller.step(
                robot_x, robot_y, robot_theta, target_x, target_y, dt, get_motion_disturbance()
            )
            robot_x = state[0]
            robot_y = state[1]
            robot_theta = state[2]
            robot_v = state[3]
            robot_omega = state[4]
            robot_pos_error = state[5]
            robot_heading_error = state[6]
            robot_wheel_commands = [robot_controller.wL, robot_controller.wL, robot_controller.wR, robot_controller.wR]

            update_robot1()

            # Check waypoint arrival using the mathematical position.
            if robot_pos_error < 0.8:
                if (wp_index % len(wp_patrol)) == PUMP_INSPECT_WP:
                    is_inspecting = True
                    inspect_timer = 0.0
                    robot_controller.reset()
                    add_log("Robot 1 stopped at Pump. Inspecting...")
                else:
                    wp_index = (wp_index + 1) % len(wp_patrol)
                    robot_controller.reset()

            robot_arm.axis = vector(
                2*cos(robot_theta),
                0,
                2*sin(robot_theta)
            )

        robot_light.color = battery_color(robot_battery)

    elif scenario_phase == 1:
        # Investigate the edge of Zone C using the same PID/IK/FK loop.
        investigate_pos = vector(12, 1, -12)
        controller_target = investigate_pos
        state = robot_controller.step(
            robot_x, robot_y, robot_theta, investigate_pos.x, investigate_pos.z, dt, get_motion_disturbance()
        )
        robot_x = state[0]
        robot_y = state[1]
        robot_theta = state[2]
        robot_v = state[3]
        robot_omega = state[4]
        robot_pos_error = state[5]
        robot_heading_error = state[6]
        robot_wheel_commands = [robot_controller.wL, robot_controller.wL, robot_controller.wR, robot_controller.wR]
        update_robot1()
        robot_arm.axis = vector(
            3.5*cos(robot_theta), 0, 3.5*sin(robot_theta)
        )
        robot_light.color = color.yellow
        robot_beacon.visible = True

    elif scenario_phase == 2:
        # RETREAT away from danger to safe corner using the same controller.
        controller_target = r1_safe_pos
        state = robot_controller.step(
            robot_x, robot_y, robot_theta, r1_safe_pos.x, r1_safe_pos.z, dt, get_motion_disturbance()
        )
        robot_x = state[0]
        robot_y = state[1]
        robot_theta = state[2]
        robot_v = state[3]
        robot_omega = state[4]
        robot_pos_error = state[5]
        robot_heading_error = state[6]
        robot_wheel_commands = [robot_controller.wL, robot_controller.wL, robot_controller.wR, robot_controller.wR]
        update_robot1()
        robot_arm.axis = vector(
            2*cos(robot_theta), 0, 2*sin(robot_theta)
        )
        robot_light.color = color.red
        robot_beacon.visible = True
        if robot_pos_error < 0.8:
            r1_retreated = True

    elif scenario_phase == 3 or scenario_phase == 4:
        # Hold at the safe zone. Wheel speeds are explicitly driven to zero.
        robot_controller.hold(dt)
        robot_v = robot_controller.v
        robot_omega = robot_controller.omega
        update_robot1()
        robot_arm.axis = vector(
            2*cos(robot_theta), 0, 2*sin(robot_theta)
        )
        robot_light.color = color.red
        robot_beacon.visible = True
        signal_ring.visible = True

    # Update zone after Robot 1 mathematical motion.
    # VPython ground uses (x, z), while the controller uses (x, y).
    current_zone = get_zone(vector(robot_x, 1, robot_y))

    # Signal ring pulse
    if signal_ring.visible:
        if signal_growing:
            signal_scale += 0.05
            signal_ring.radius = signal_scale
            if signal_scale > 4.0: signal_growing = False
        else:
            signal_scale -= 0.05
            signal_ring.radius = signal_scale
            if signal_scale < 1.0: signal_growing = True

    # ================================================
    # ROBOT 2
    # ================================================

    if scenario_phase >= 3:
        if not r2_arrived:
            move_result = move_toward(robot2_body.pos, r2_target, 0.14)
            new_pos2 = move_result[0]
            r2_arrived = move_result[1]
            update_robot2(new_pos2)
        else:
            update_robot2(r2_target)
        if scenario_phase >= 4:
            robot2_arm.axis    = vector(4, 0, 0)
            robot2_light.color = color.white   # white = spray active
        else:
            robot2_arm.axis    = vector(2, 0, 0)
            robot2_light.color = color.red

    # ================================================
    # DISTANCE: Robot <-> Drone
    # ================================================

    robot_drone_dist = mag(drone_body.pos - robot_body.pos)
    conn_status_str  = "STRONG" if robot_drone_dist < 30 else ("WEAK" if robot_drone_dist < 45 else "LOST")

    # ================================================
    # WIRELESS SIGNAL ANIMATION
    # Rings expand outward from robot & drone
    # ================================================

    signal_ring_timer += dt

    # Robot transmit rings - expand and fade out
    for i, sr in enumerate(signal_rings):
        phase = (signal_ring_timer + signal_ring_phase[i]) % 1.2
        sr.pos     = robot_body.pos + vector(0, 1.5, 0)
        sr.radius  = 0.5 + phase * 4.0          # expand from 0.5 to 5.3
        sr.opacity = max(0, 0.7 - phase * 0.6)  # fade as it expands
        # color based on signal strength
        if conn_status_str == "STRONG":
            sr.color = color.cyan
        elif conn_status_str == "WEAK":
            sr.color = color.yellow
        else:
            sr.color = color.red

    # Drone receive rings - smaller, yellow
    for i, dr in enumerate(drone_rings):
        phase = (signal_ring_timer + drone_ring_phase[i]) % 1.0
        dr.pos     = drone_body.pos + vector(0, 0.5, 0)
        dr.radius  = 0.3 + phase * 2.5
        dr.opacity = max(0, 0.5 - phase * 0.5)
        dr.color   = color.cyan if conn_status_str == "STRONG" else (color.yellow if conn_status_str == "WEAK" else color.red)

    # Sync delay: if signal weak/lost, data updates slower
    sync_delay_counter += 1
    sync_interval = 1 if conn_status_str == "STRONG" else (3 if conn_status_str == "WEAK" else 8)
    if sync_delay_counter >= sync_interval:
        sync_delay_counter = 0
        synced_data["gas"]      = gas
        synced_data["temp"]     = temperature
        synced_data["rad"]      = radiation
        synced_data["pressure"] = pressure

    # ================================================
    # DRONE
    # ================================================

    drone_angle += 0.01 if scenario_phase <= 1 else 0.025
    if scenario_phase >= 2:
        dtarget = vector(5, 10, -15)
    else:
        # Drone loosely follows robot horizontally + stays high
        follow_x = robot_body.pos.x * 0.3 + drone_radius * sin(drone_angle) * 0.7
        follow_z = robot_body.pos.z * 0.3 + drone_radius * cos(drone_angle) * 0.7
        dtarget   = vector(follow_x, 18, follow_z)

    drone_body.pos += (dtarget - drone_body.pos) * 0.02
    drone_label.pos = drone_body.pos + vector(0, 2.5, 0)
    drone_arm1.pos  = drone_body.pos
    drone_arm2.pos  = drone_body.pos

    r_offs = [vector(2.5,0.2,0),vector(-2.5,0.2,0),vector(0,0.2,2.5),vector(0,0.2,-2.5)]
    for r, off in zip([rotor1,rotor2,rotor3,rotor4], r_offs):
        r.pos = drone_body.pos + off
    rotor1.axis = vector(1.5*cos(rotor_angle),      0.1, 1.5*sin(rotor_angle))
    rotor2.axis = vector(1.5*cos(rotor_angle+pi),   0.1, 1.5*sin(rotor_angle+pi))
    rotor3.axis = vector(1.5*cos(rotor_angle+pi/2), 0.1, 1.5*sin(rotor_angle+pi/2))
    rotor4.axis = vector(1.5*cos(rotor_angle-pi/2), 0.1, 1.5*sin(rotor_angle-pi/2))

    # ================================================
    # SPRAY, GAS CLOUD, FIRE
    # ================================================

    if scenario_phase == 4:
        for i, sp in enumerate(spray_particles):
            angle_i = spray_angle + i*(2*pi/len(spray_particles))
            sp.color   = color.white
            sp.opacity = 0.3 + random()*0.5   # flickering mist effect
            sp.radius  = 0.2 + random()*0.25  # particles vary in size
            sp.pos = vector(
                r2_target.x + 2 + random()*3,
                r2_target.y + random()*2.5,
                r2_target.z + sin(angle_i)*1.5
            )
    else:
        for sp in spray_particles:
            sp.opacity = 0.0

    if scenario_phase >= 1:
        grow = min(0.55, (scenario_timer-80)/60.0)
        if scenario_phase >= 4:
            grow = max(0, grow - (scenario_timer-190)*0.005)
        for g in gas_cloud:
            g.opacity = grow
            g.pos.y  += 0.03
            g.pos.x  += (random()-0.5)*0.04
            if g.pos.y > 6: g.pos.y = 0.5
    else:
        for g in gas_cloud: g.opacity = 0

    if scenario_phase == 3:
        for f in fire_particles:
            f.opacity = 0.8
            f.color   = random_choice([color.red, color.orange, color.yellow])
            f.pos.y  += 0.08
            if f.pos.y > 5: f.pos.y = 0.5
    else:
        for f in fire_particles: f.opacity = 0.0

    if scenario_phase >= 5 and containment.opacity < 0.3:
        containment.opacity += 0.001

    # ================================================
    # WORKERS
    # ================================================

    if scenario_phase >= 2:
        for i, (wb, wl) in enumerate(workers):
            dw = w_targets[i] - wb.pos
            if mag(dw) > 0.5:
                wb.pos += norm(dw) * 0.1
                wl.pos  = wb.pos + vector(0,0.7,0)

    # ================================================
    # WARNING LIGHTS
    # ================================================

    if flash_timer > 0.4:
        flash_timer = 0
        if scenario_phase >= 1:
            warn_a.visible = not warn_a.visible
            warn_c.visible = not warn_c.visible

    # ================================================
    # STEAM & BUBBLES
    # ================================================

    for s in steam:
        s.pos.y += 0.05
        if s.pos.y > 28: s.pos.y = 16
    for b in bubbles:
        b.pos.y += 0.05
        if b.pos.y > 2: b.pos.y = 0.2

    # ================================================
    # SENSOR + DASHBOARD UPDATE
    # ================================================

    sensor_timer += dt
    control_plot_timer += dt

    # Plot controller data at the same simulation-time interval as the
    # environmental/process graphs, rather than refreshing at 10 Hz.
    # This keeps graph timestamps consistent when simulation speed changes.
    if control_plot_timer >= update_interval:
        control_plot_timer = 0.0
        sim_t = scenario_timer
        # Update only the graph set belonging to the currently selected
        # controller. The other controller's graph history remains unchanged.
        # Both graph sets already have initial samples from t=0, so both are
        # visible immediately; an unselected controller's curves stay frozen.
        # Position/heading error graphs have been removed as requested.
        if controller_mode == "SMC":
            smc_actual_traj_curve.plot(robot_x, robot_y)
            smc_vref_curve.plot(sim_t, robot_controller.v_cmd)
            smc_vactual_curve.plot(sim_t, robot_controller.v)
            smc_wref_curve.plot(sim_t, robot_controller.omega_cmd)
            smc_wactual_curve.plot(sim_t, robot_controller.omega)
            smc_wheel_l_curve.plot(sim_t, robot_controller.wL)
            smc_wheel_r_curve.plot(sim_t, robot_controller.wR)
            smc_tau_l_curve.plot(sim_t, robot_controller.tau_L)
            smc_tau_r_curve.plot(sim_t, robot_controller.tau_R)
            smc_acc_v_curve.plot(sim_t, robot_controller.v_dot)
            smc_acc_w_curve.plot(sim_t, robot_controller.omega_dot)
        else:
            pid_actual_traj_curve.plot(robot_x, robot_y)
            pid_vref_curve.plot(sim_t, robot_controller.v_cmd)
            pid_vactual_curve.plot(sim_t, robot_controller.v)
            pid_wref_curve.plot(sim_t, robot_controller.omega_cmd)
            pid_wactual_curve.plot(sim_t, robot_controller.omega)
            pid_wheel_l_curve.plot(sim_t, robot_controller.wL)
            pid_wheel_r_curve.plot(sim_t, robot_controller.wR)
            pid_tau_l_curve.plot(sim_t, robot_controller.tau_L)
            pid_tau_r_curve.plot(sim_t, robot_controller.tau_R)
            pid_acc_v_curve.plot(sim_t, robot_controller.v_dot)
            pid_acc_w_curve.plot(sim_t, robot_controller.omega_dot)

    if sensor_timer > update_interval:
        sensor_timer = 0
        reaction_timer += 1
        time_counter += 1

        # ------------------------------------------------
        # Environmental process model
        # ------------------------------------------------
        # Each phase defines a target plant condition. A first-order response
        # produces smooth changes rather than arbitrary jumps.
        if scenario_phase == 0:
            t_target = 31.5
            p_target = 102.0
            r_target = 5.0
            leak_strength = 0.0
        elif scenario_phase == 1:
            t_target = 36.0
            p_target = 104.0
            r_target = 7.5
            leak_strength = 6.0
        elif scenario_phase == 2:
            t_target = 43.0
            p_target = 109.0
            r_target = 11.5
            leak_strength = 8.0
        elif scenario_phase == 3:
            t_target = 51.0
            p_target = 114.0
            r_target = 15.0
            leak_strength = 10.0
        elif scenario_phase == 4:
            t_target = 38.0
            p_target = 105.0
            r_target = 7.0
            leak_strength = 3.0
        else:
            t_target = 31.0
            p_target = 102.0
            r_target = 5.0
            leak_strength = 0.0

        # Plant-process coupling: pool temperature influences equipment
        # temperature, while manual anomaly tests add localized hazards.
        t_target += 0.12 * max(0.0, plant_pool.temperature - 32.0)
        if manual_anomaly == ANOMALY_STEAM:
            t_target += 5.0
        if manual_anomaly == ANOMALY_FIRE:
            t_target += 8.0
            p_target += 3.0
        if manual_anomaly == ANOMALY_RADIATION:
            r_target += 12.0

        # Distance-based gas concentration model around the simulated leak
        # source at Zone C: G(d) = G_max * exp(-k*d).
        leak_x = 5.0
        leak_y = -15.0
        leak_distance = ((robot_x-leak_x)**2 + (robot_y-leak_y)**2) ** 0.5
        gas_from_leak = leak_strength * exp(-0.08*leak_distance)
        if manual_anomaly == ANOMALY_COOLANT:
            gas_from_leak += 1.5 * exp(-0.10*leak_distance)
        g_target = 0.3 + gas_from_leak
        if manual_anomaly == ANOMALY_RADIATION:
            hot_distance = ((robot_x+25.0)**2 + (robot_y+5.0)**2) ** 0.5
            radiation += 4.0 * exp(-0.12*hot_distance)

        process_alpha = 0.30
        temperature += process_alpha * (t_target - temperature)
        pressure += process_alpha * (p_target - pressure)
        radiation += process_alpha * (r_target - radiation)
        gas += process_alpha * (g_target - gas)

        # ------------------------------------------------
        # Dataset-backed sensor readings + optional simulation anomalies.
        # Uploaded dataset supplies recorded radiation/temperature/contamination
        # and risk labels; the robot motion controller remains simulation-based.
        # ------------------------------------------------
        if len(dataset_record) > 0:
            temp_measured = max(0.0, dataset_record["Temperature"])
            rad_measured = max(0.0, dataset_record["Radiation"])
            gas_measured = max(0.0, dataset_record["Water_Contamination"])
            pressure = dataset_record["Pressure"]
        else:
            temp_measured = max(0.0, temperature + (random()-0.5)*2*SENSOR_NOISE_TEMP)
            rad_measured = max(0.0, radiation + (random()-0.5)*2*SENSOR_NOISE_RAD)
            gas_measured = max(0.0, gas + (random()-0.5)*2*SENSOR_NOISE_GAS)


        temp_filtered = FILTER_ALPHA*temp_measured + (1-FILTER_ALPHA)*temp_filtered
        rad_filtered = FILTER_ALPHA*rad_measured + (1-FILTER_ALPHA)*rad_filtered
        gas_filtered = FILTER_ALPHA*gas_measured + (1-FILTER_ALPHA)*gas_filtered

        # Normalized risk score: radiation is given the largest weight for
        # this nuclear-inspection demonstration.
        temp_n = min(temp_filtered / 60.0, 1.0)
        rad_n = min(rad_filtered / 15.0, 1.0)
        gas_n = min(gas_filtered / 8.0, 1.0)
        risk_score = 100.0 * (0.25*temp_n + 0.50*rad_n + 0.25*gas_n)
        if len(dataset_record) > 0:
            # Use the dataset's recorded risk score/level for the live data panel.
            risk_score = clamp(dataset_record["Risk_Score"], 0.0, 100.0)

        if risk_score < 30:
            alert_level = 0
        elif risk_score < 50:
            alert_level = 1
        elif risk_score < 70:
            alert_level = 2
        else:
            alert_level = 3

        # Use filtered values as the synchronized inspection readings.
        synced_data["temp"] = temp_filtered
        synced_data["rad"] = rad_filtered
        synced_data["gas"] = gas_filtered
        synced_data["pressure"] = pressure

        # Update floating name label colors based on alert
        robot1_label.color = alert_colors[alert_level]
        robot1_label.text  = ("🤖 R1-INSPECTOR  [" + ("RETREATED" if scenario_phase in [2,3,4] else "PATROLLING") + "]")
        drone_label.color  = alert_colors[alert_level]
        drone_label.text   = ("✈ DRONE-1  [" + ("SCANNING LEAK" if scenario_phase >= 2 else "AERIAL PATROL") + "]")
        if scenario_phase >= 3:
            robot2_label.color = color.red if scenario_phase == 3 else color.cyan
            robot2_label.text  = ("🛡 R2-RESPONDER  [" + ("MOVING" if scenario_phase == 3 else "SUPPRESSING") + "]")
        r1_mode = ["NORMAL PATROL","INVESTIGATING ZONE C","RETREATING TO SAFE ZONE",
                   "AT SAFE ZONE - ALERTING","AT SAFE ZONE - MONITORING","RESUMING PATROL"][scenario_phase]
        r1_inspect_txt = ("INSPECTING (" + str(round(inspect_timer,1)) + "/" + str(INSPECT_DURATION) + "s)" if is_inspecting else "MOVING")

        # Compact Robot 1 panel: remove duplicate controller/torque lines so
        # its box stays inside its own dashboard slot.
        robot_panel.text = (
            "ROBOT 1  (PATROL / DETECTOR)\n"
            "Status    : " + r1_mode + "\n"
            "Zone      : " + current_zone + "\n"
            "Position  : (" + str(round(robot_body.pos.x,1)) + ", " + str(round(robot_body.pos.z,1)) + ")\n"
            "Pump Stop : " + r1_inspect_txt + "\n"
            "Battery   : " + str(round(robot_battery,1)) + "% " + ("LOW" if robot_battery_low else "OK") + "\n"
            "Theta     : " + str(round(robot_theta,2)) + " rad\n"
            "v / omega : " + str(round(robot_v,2)) + " / " + str(round(robot_omega,2)) + "\n"
            "Pos Error : " + str(round(robot_pos_error,2)) + " m\n"
            "Head Err  : " + str(round(robot_heading_error,2)) + " rad\n"
            "Wheel L/R : " + str(round(robot_controller.wL,2)) + " / " + str(round(robot_controller.wR,2)) + " rad/s\n"
            "Controller: " + controller_mode + "\n"
            "Torque L/R: " + str(round(robot_controller.tau_L,2)) + " / " + str(round(robot_controller.tau_R,2)) + " Nm\n"
            "v_dot/w_dot: " + str(round(robot_controller.v_dot,2)) + " / " + str(round(robot_controller.omega_dot,2))
        )

        r2_mode = ["STANDBY","STANDBY","STANDBY","MOVING TO ZONE C","SUPPRESSING GAS","SEALED - DONE"][scenario_phase]
        robot2_panel.text = (
            "ROBOT 2  (SHIELDED RESPONDER)\n"
            "Status    : " + r2_mode + "\n"
            "Shield    : " + ("ACTIVE" if scenario_phase >= 3 else "OFF") + "\n"
            "Spray Arm : " + ("ACTIVE" if scenario_phase == 4 else "OFF") + "\n"
            "Position  : (" + str(round(robot2_body.pos.x,1)) + ", " + str(round(robot2_body.pos.z,1)) + ")"
        )

        conn_status = "STRONG" if robot_drone_dist < 30 else ("WEAK" if robot_drone_dist < 45 else "LOST")
        drone_panel.text = (
            "DRONE  (AERIAL MONITOR)\n"
            "Battery   : " + str(round(drone_battery,1)) + "% " + ("!!! LOW !!!" if drone_battery_low else "OK") + "\n"
            "Altitude  : " + str(round(drone_body.pos.y,1)) + " m\n"
            "Temp      : " + str(round(synced_data["temp"],2)) + " C\n"
            "Gas       : " + str(round(synced_data["gas"],2)) + " ppm\n"
            "Mode      : " + ("SCANNING LEAK SITE" if scenario_phase >= 2 else "AERIAL PATROL")
        )

        connect_panel.text = (
            "WIRELESS COMMS  [Robot <-> Drone]\n\n"
            "Signal Strength : " + conn_status + "\n"
            "Distance        : " + str(round(robot_drone_dist,1)) + " m\n"
            "Sync Status     : " + ("REAL-TIME" if conn_status=="STRONG" else ("DELAYED" if conn_status=="WEAK" else "NO SIGNAL")) + "\n\n"
            "SYNCED SENSOR DATA\n"
            "Radiation  : " + str(round(synced_data["rad"],2)) + " mSv\n"
            "Gas        : " + str(round(synced_data["gas"],2)) + " ppm\n"
            "Temp       : " + str(round(synced_data["temp"],1)) + " C\n"
            "Pressure   : " + str(round(synced_data["pressure"],1)) + " kPa"
        )

        alarm_panel.background = alert_colors[alert_level]
        alarm_panel.text = (
            "ALERT LEVEL " + str(alert_level) + " : " + alert_names[alert_level] + "\n"
            "Gas: " + str(round(gas,2)) + " ppm  |  Rad: " + str(round(radiation,2)) + " mSv  |  Temp: " + str(round(temperature,1)) + " C\n" +
            "Pool: " + str(round(plant_pool.level,2)) + " m | " + ("MANUAL TEST ACTIVE" if manual_anomaly_active else "AUTO SCENARIO")
        )

        phase_panel.text       = "  " + phase_labels[scenario_phase] + "   [ T=" + str(round(scenario_timer,1)) + "s ]  "
        phase_panel.background = alert_colors[alert_level]

        # Compact live telemetry matching the second Web-VPython model.
        if manual_anomaly_active:
            status_now = "MANUAL TEST: " + ("COOLANT LEAK" if manual_anomaly == ANOMALY_COOLANT else "STEAM RUPTURE" if manual_anomaly == ANOMALY_STEAM else "RADIATION HOTSPOT" if manual_anomaly == ANOMALY_RADIATION else "TRANSFORMER FIRE")
        elif alert_level >= 3:
            status_now = "EMERGENCY"
        elif alert_level == 2:
            status_now = "WARNING"
        elif alert_level == 1:
            status_now = "CAUTION"
        else:
            status_now = "NORMAL"
        status_text.text = "SYSTEM: " + status_now
        telemetry.text = (
            "TIME: " + str(round(scenario_timer,1)) + " s | "
            "POWER: " + str(round(power,0)) + " % | "
            "POOL: " + str(round(plant_pool.level,2)) + " m | "
            "POOL TEMP: " + str(round(plant_pool.temperature,1)) + " C | "
            "PUMP: " + str(round(plant_pool.flow,2)) + " | "
            "LEAK: " + str(round(plant_pool.leak,2)) + "\n"
            "DRONE: (" + str(round(drone_body.pos.x,1)) + ", " + str(round(drone_body.pos.y,1)) + ", " + str(round(drone_body.pos.z,1)) + ") | "
            "BATTERY: " + str(round(drone_battery,1)) + " % | "
            "ROVER SPEED: " + str(round(abs(robot_v),2)) + " m/s | "
            "ROVER BATTERY: " + str(round(robot_battery,1)) + " % | "
            "RADIATION: " + str(round(radiation,2)) + " | "
            "DATA ROW: " + str(dataset_index+1) + "/" + str(len(dataset_rows)) + " | "
            "DATA RISK: " + str(round(dataset_record["Risk_Score"],1) if len(dataset_record)>0 else 0)
        )

        zone_panel.text = (
            "ZONE STATUS\n\n"
            "Zone A (Reactor)  : " + str(round(4+random()*2+(1 if scenario_phase>=2 else 0),1)) + " mSv\n"
            "Zone B (Turbine)  : " + str(round(3+random()*1.5,1)) + " mSv\n"
            "Zone C (Pump)     : " + ("DANGER " + str(round(gas,1)) + " ppm" if scenario_phase>=1 else "Normal") + "\n"
            "Zone D (Cooling)  : " + str(round(2+random()*2,1)) + " mSv\n"
            "Control Room      : NO ENTRY (enforced)\n\n"
            "Workers           : " + ("EVACUATED" if scenario_phase>=2 else "On Duty") + "\n"
            "Robot 2           : " + ("ACTIVE" if scenario_phase>=3 else "Standby") + "\n"
            "Containment       : " + ("ACTIVE" if scenario_phase>=5 else "Pending") + "\n"
            "Pool Level        : " + str(round(plant_pool.level,2)) + " m\n"
            "Pool Temperature  : " + str(round(plant_pool.temperature,1)) + " C"
        )

        action_log.text = "ROBOT ACTION LOG\n\n" + "\n".join(log_lines)

        # Integrated plant-process telemetry: only the important process graph.
        pool_level_curve.plot(scenario_timer, plant_pool.level)
        pool_set_curve.plot(scenario_timer, pool_setpoint)